-- Blank mark sheets generated by the Headmaster: kept exactly as generated (subjects, maximum marks, students).
CREATE TABLE `blank_mark_sheets` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `school_id` BIGINT UNSIGNED NOT NULL,
  `sheet_no` VARCHAR(30) NOT NULL,
  `exam_id` BIGINT UNSIGNED NOT NULL,
  `section_id` BIGINT UNSIGNED NOT NULL,
  `class_subject_id` BIGINT UNSIGNED NULL,
  `with_names` TINYINT(1) NOT NULL DEFAULT 0,
  `subjects` VARCHAR(500) NOT NULL,
  `data` JSON NOT NULL,
  `generated_by` BIGINT UNSIGNED NOT NULL,
  `generated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE INDEX `blank_mark_sheets_school_id_sheet_no_key` (`school_id`, `sheet_no`),
  INDEX `blank_mark_sheets_school_id_generated_at_idx` (`school_id`, `generated_at`),
  CONSTRAINT `blank_mark_sheets_exam_id_fkey` FOREIGN KEY (`exam_id`) REFERENCES `exams` (`id`),
  CONSTRAINT `blank_mark_sheets_section_id_fkey` FOREIGN KEY (`section_id`) REFERENCES `sections` (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
